from rules import candidates, closes_cycle


def solve(data):
    packages = data.get('packages', {})
    names = sorted(packages)
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))

    constraints = {}
    for name, bounds in roots.items():
        constraints.setdefault(name, []).append((bounds[0], bounds[1]))

    best_key = None
    best_versions = None
    maximums = {
        name: max((row['version'] for row in rows), default=-1)
        for name, rows in packages.items()
    }

    def search(assigned, limits, graph):
        nonlocal best_key, best_versions

        active = set(limits)
        domains = {}
        for name in active:
            domain = candidates(
                packages.get(name, []), limits[name], blocked.get(name, []),
                name in pins, pins.get(name)
            )
            if not domain:
                return
            if name in assigned:
                if not any(row['version'] == assigned[name]['version']
                           and row is assigned[name] for row in domain):
                    return
            else:
                domains[name] = domain

        upper = tuple(
            assigned[name]['version'] if name in assigned else
            max((row['version'] for row in domains[name]), default=-1)
            if name in active else max(-1, maximums.get(name, -1))
            for name in names
        )
        if best_key is not None and upper <= best_key:
            return

        pending = [name for name in active if name not in assigned]
        if not pending:
            key = tuple(assigned[name]['version'] if name in assigned else -1
                        for name in names)
            if best_key is None or key > best_key:
                best_key = key
                best_versions = {name: assigned[name]['version'] for name in assigned}
            return

        name = min(pending)
        for row in domains[name]:
            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_limits = {key: list(value) for key, value in limits.items()}
            next_graph = {key: set(value) for key, value in graph.items()}
            next_graph.setdefault(name, set())
            valid = True
            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                target = dep['name']
                if closes_cycle(next_graph, name, target):
                    valid = False
                    break
                next_graph.setdefault(name, set()).add(target)
                next_graph.setdefault(target, set())
                next_limits.setdefault(target, []).append((dep['min'], dep['max']))
            if valid:
                search(next_assigned, next_limits, next_graph)

    search({}, constraints, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def candidates(rows, constraints, blocked, has_pin, pin):
    forbidden = set(blocked)
    result = []
    for row in rows:
        version = row['version']
        if version in forbidden:
            continue
        if has_pin and version != pin:
            continue
        if all(low <= version <= high for low, high in constraints):
            result.append(row)
    return sorted(result, key=lambda row: row['version'], reverse=True)


def closes_cycle(graph, source, target):
    if source == target:
        return True
    todo = [target]
    seen = set()
    while todo:
        node = todo.pop()
        if node == source:
            return True
        if node in seen:
            continue
        seen.add(node)
        todo.extend(graph.get(node, ()))
    return False
